Here's a systematic audit approach so you catch everything:

```bash
# Find every process.on() and process.addListener() in your middleware
grep -rn 'process\.on\|process\.addListener\|server\.on' src/middleware/
```

**The rule is simple:** if it's inside a `(req, res, next) =>` function and it calls `.on()` on any object that outlives the request (process, server, a module-level EventEmitter), it's a leak.

You should also check whether you've been suppressing Node's built-in warning:

```javascript
// If you have this anywhere, REMOVE IT:
process.setMaxListeners(0); // or Infinity
// Node warns you at 10 listeners for a reason — it's a leak detector
```

**Prevent this from recurring with a simple load test:**

```javascript
// test/leak-check.js — run after every middleware change
const { execSync } = require('child_process');

function getListenerCounts() {
  return {
    uncaughtException: process.listenerCount('uncaughtException'),
    unhandledRejection: process.listenerCount('unhandledRejection'),
    SIGTERM: process.listenerCount('SIGTERM'),
  };
}

async function checkForLeaks(app, port) {
  const before = getListenerCounts();

  // Send 100 requests
  for (let i = 0; i < 100; i++) {
    await fetch(`http://localhost:${port}/api/health`);
  }

  const after = getListenerCounts();

  for (const [event, count] of Object.entries(after)) {
    if (count > before[event]) {
      console.error(
        `LEAK: ${event} listeners grew from ${before[event]} to ${count} after 100 requests`
      );
      process.exit(1);
    }
  }
  console.log('No listener leaks detected.');
}
```

